  `,
  lg: css`
    padding: 0.75rem 1.75rem;
    font-size: 1.0625rem;
    border-radius: 10px;
    gap: 0.625rem;
  `,
};

// ─── Variant Map ──────────────────────────────────────────────────────────────

const variantStyles = {
  solid: css`
    background: var(--btn-primary);
    color: #ffffff;
    border: 2px solid transparent;

    &:hover:not(:disabled) {
      background: var(--btn-primary-hover);
