const StyledButton = styled.button<{
  $size: ButtonSize;
  $variant: ButtonVariant;
  $fullWidth: boolean;
  $isLoading: boolean;
}>`
  /* CSS custom properties (theme tokens) */
  --btn-primary: #4f46e5;
  --btn-primary-hover: #4338ca;
  --btn-primary-active: #3730a3;
  --btn-primary-subtle: rgba(79, 70, 229, 0.08);
  --btn-primary-subtle-active: rgba(79, 70, 229, 0.16);
  --btn-shadow: rgba(79, 70, 229, 0.35);
  --btn-disabled-bg: #e2e8f0;
  --btn-disabled-text: #94a3b8;

  /* Base styles */
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  font-family: inherit;
  font-weight: 600;
  letter-spacing: 0.01em;
  line-height: 1;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background 200ms ease,
    color 200ms ease,
    border-color 200ms ease,
    box-shadow 200ms ease,
    transform 150ms ease,
    opacity 200ms ease;
  outline-offset: 3px;

  /* Size */
  ${({ $size }) => sizeStyles[$size]}

  /* Variant */
  ${({ $variant }) => variantStyles[$variant]}

  /* Full width */
  ${({ $fullWidth }) => $fullWidth && css`width: 100%;`}

  /* Loading state — keep layout, hide text interaction */
  ${({ $isLoading }) =>
    $isLoading &&
    css`
      cursor: wait;
      pointer-events: none;
    `}

  /* Disabled state */
  &:disabled {
    cursor: not-allowed;
    background: var(--btn-disabled-bg);
    color: var(--btn-disabled-text);
    border-color: transparent;
    box-shadow: none;
    transform: none;
    opacity: 0.7;
  }

  /* Focus-visible ring */
  &:focus-visible {
    outline: 3px solid var(--btn-primary);
    outline-offset: 3px;
  }

  /* Ripple child */
  .ripple {
    position: absolute;
    border-radius: 50%;
    width: 10px;
    height: 10px;
    background: rgba(255, 255, 255, 0.45);
    animation: ${ripple} 600ms linear forwards;
    pointer-events: none;
  }
`;

const Spinner = styled.span`
  display: inline-flex;
  width: 1em;
  height: 1em;
  border: 2px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: ${spin} 650ms linear infinite;
  flex-shrink: 0;
`;

const IconWrapper = styled.span`
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  font-size: 1.1em;
`;

const LabelWrapper = styled.span<{ $hidden: boolean }>`
  ${({ $hidden }) =>
    $hidden &&
    css`
      visibility: hidden;
      width: 0;
      overflow: hidden;
    `}
`;

// ─── Component ────────────────────────────────────────────────────────────────

const PrimaryButton: React.FC<PrimaryButtonProps> = ({
  label,
  size = "md",
  variant = "solid",
  isLoading = false,
  leftIcon,
  rightIcon,
  fullWidth = false,
  disabled,
  onClick,
  ...rest
}) => {
  // ── Ripple effect ──────────────────────────────────────────────────────────
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    const btn = e.currentTarget;
    const circle = document.createElement("span");
    const rect = btn.getBoundingClientRect();

    circle.className = "ripple";
    circle.style.left = `${e.clientX - rect.left - 5}px`;
    circle.style.top = `${e.clientY - rect.top - 5}px`;

    btn.appendChild(circle);
    circle.addEventListener("animationend", () => circle.remove());

    onClick?.(e);
  };

  const isDisabled = disabled || isLoading;

  return (
    <StyledButton
      $size={size}
      $variant={variant}
      $fullWidth={fullWidth}
      $isLoading={isLoading}
      disabled={isDisabled}
      onClick={handleClick}
      aria-busy={isLoading}
      aria-label={isLoading ? `${label} — loading` : label}
      {...rest}
    >
      {/* Left icon or spinner */}
      {isLoading ? (
        <Spinner aria-hidden="true" />
      ) : leftIcon ? (
        <IconWrapper aria-hidden="true">{leftIcon}</IconWrapper>
      ) : null}

      {/* Label */}
      <LabelWrapper $hidden={isLoading && !leftIcon && !rightIcon}>
        {label}
      </LabelWrapper>

      {/* Right icon */}
      {!isLoading && rightIcon && (
        <IconWrapper aria-hidden="true">{rightIcon}</IconWrapper>
      )}
    </StyledButton>
  );
};

export default PrimaryButton;
