  ghost: css`
    background: transparent;
    color: #6366f1;
    border: 2px solid transparent;

    &:hover:not(:disabled) {
      background: rgba(99, 102, 241, 0.1);
      color: #4f46e5;
      transform: translateY(-1px);
    }

    &:active:not(:disabled) {
      background: rgba(99, 102, 241, 0.18);
      transform: translateY(0);
    }
  `,
};

// ─── Styled Components ────────────────────────────────────────────────────────

const StyledButton = styled.button<{
  $size: ButtonSize;
  $variant: ButtonVariant;
  $fullWidth: boolean;
  $isLoading: boolean;
}>`
  /* Layout */
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  width: ${({ $fullWidth }) => ($fullWidth ? "100%" : "auto")};

  /* Typography */
  font-family: inherit;
  font-weight: 600;
  letter-spacing: 0.01em;
  white-space: nowrap;
  line-height: 1.5;

  /* Interaction */
  cursor: ${({ $isLoading }) => ($isLoading ? "wait" : "pointer")};
  user-select: none;
  outline: none;

  /* Transition */
  transition:
    background 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.15s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    opacity 0.2s ease;

  /* Size */
  ${({ $size }) => sizeStyles[$size]}

  /* Variant */
  ${({ $variant }) => variantStyles[$variant]}

  /* Focus ring */
  &:focus-visible {
    outline: 3px solid rgba(99, 102, 241, 0.5);
    outline-offset: 3px;
  }

  /* Disabled */
  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    transform: none;
    box-shadow: none;
    filter: grayscale(20%);
  }

  /* Ripple child */
  .ripple {
    position: absolute;
    border-radius: 50%;
    width: 60px;
    height: 60px;
    background: rgba(255, 255, 255, 0.35);
    animation: ${ripple} 0.55s linear;
    pointer-events: none;
  }
`;

const Spinner = styled.span`
  display: inline-block;
  width: 1em;
  height: 1em;
  border: 2px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: ${spin} 0.7s linear infinite;
  flex-shrink: 0;
`;

const IconWrapper = styled.span`
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  font-size: 1.1em;
`;

const LabelWrapper = styled.span<{ $hidden: boolean }>`
  transition: opacity 0.2s ease;
  opacity: ${({ $hidden }) => ($hidden ? 0 : 1)};
`;

// ─── Component ────────────────────────────────────────────────────────────────

export const PrimaryButton: React.FC<PrimaryButtonProps> = ({
  label,
  size = "md",
  variant = "solid",
  isLoading = false,
  leftIcon,
  rightIcon,
  fullWidth = false,
  disabled,
  onClick,
  ...rest
}) => {
  // ── Ripple effect ──────────────────────────────────────────────────────────
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (disabled || isLoading) return;

    const button = e.currentTarget;
    const circle = document.createElement("span");
    const rect = button.getBoundingClientRect();

    circle.className = "ripple";
    circle.style.left = `${e.clientX - rect.left - 30}px`;
    circle.style.top = `${e.clientY - rect.top - 30}px`;

    button.appendChild(circle);
    setTimeout(() => circle.remove(), 560);

    onClick?.(e);
  };

  return (
    <StyledButton
      $size={size}
      $variant={variant}
      $fullWidth={fullWidth}
      $isLoading={isLoading}
      disabled={disabled || isLoading}
      onClick={handleClick}
      aria-busy={isLoading}
      aria-label={isLoading ? `${label} – loading` : label}
      {...rest}
    >
      {/* Left icon or spinner */}
      {isLoading ? (
        <Spinner aria-hidden="true" />
      ) : (
        leftIcon && <IconWrapper aria-hidden="true">{leftIcon}</IconWrapper>
      )}

      {/* Label */}
      <LabelWrapper $hidden={false}>{label}</LabelWrapper>

      {/* Right icon (hidden while loading) */}
      {!isLoading && rightIcon && (
        <IconWrapper aria-hidden="true">{rightIcon}</IconWrapper>
      )}
    </StyledButton>
  );
};

export default PrimaryButton;
```

