  fullWidth = false,
  disabled,
  onClick,
  type = "button",
  ...rest
}) => {
  return (
    <StyledButton
      type={type}
      disabled={disabled || isLoading}
      $size={size}
      $variant={variant}
      $fullWidth={fullWidth}
      $isLoading={isLoading}
      aria-busy={isLoading}
      aria-label={isLoading ? `${label} – loading` : label}
      onClick={onClick}
      {...rest}
    >
      {isLoading ? (
        <Spinner aria-hidden="true" />
      ) : leftIcon ? (
        <IconWrapper aria-hidden="true">{leftIcon}</IconWrapper>
      ) : null}

      <LabelWrapper $hidden={false}>{label}</LabelWrapper>

      {!isLoading && rightIcon && (
        <IconWrapper aria-hidden="true">{rightIcon}</IconWrapper>
      )}
    </StyledButton>
  );
};

export default PrimaryButton;
```

