## State Summary

| State | Visual Effect |
|---|---|
| **Default** | Indigo gradient, subtle shadow |
| **Hover** | Lighter gradient, elevated shadow, 1px lift |
| **Active / Click** | Darker gradient, ripple effect, pressed down |
| **Focus** | Accessible 3px indigo outline ring |
| **Disabled** | 45% opacity, grayscale tint, `not-allowed` cursor |
| **Loading** | Spinning indicator, `wait` cursor, `aria-busy` set |

## Key Design Decisions

- **`$`-prefixed transient props** (`$size`, `$variant`) prevent DOM leakage
- **`pointer-events: none`** on disabled/loading prevents all interactions without relying solely on the `disabled` attribute
- **`aria-busy` + `aria-label`** keep screen readers informed during loading
- **`focus-visible`** shows the focus ring only for keyboard users, not mouse clicks
- **Ripple effect** via `::after` pseudo-element + keyframe — no extra DOM nodes needed

# Primary Action Button Component

## Component Implementation

```tsx
// PrimaryButton.tsx
import React, { ButtonHTMLAttributes } from "react";
import styled, { css, keyframes } from "styled-components";

// ─── Types ────────────────────────────────────────────────────────────────────

type ButtonSize = "sm" | "md" | "lg";
type ButtonVariant = "solid" | "outline" | "ghost";

interface PrimaryButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  label: string;
  size?: ButtonSize;
  variant?: ButtonVariant;
  isLoading?: boolean;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  fullWidth?: boolean;
}

// ─── Animations ───────────────────────────────────────────────────────────────

const spin = keyframes`
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
`;

const ripple = keyframes`
  0%   { transform: scale(0); opacity: 0.6; }
  100% { transform: scale(4); opacity: 0; }
`;

// ─── Size Map ─────────────────────────────────────────────────────────────────

const sizeMap: Record<ButtonSize, ReturnType<typeof css>> = {
  sm: css`
    padding: 0.375rem 0.875rem;
    font-size: 0.8125rem;
    border-radius: 6px;
    gap: 0.375rem;
  `,
  md: css`
    padding: 0.625rem 1.25rem;
    font-size: 0.9375rem;
    border-radius: 8px;
    gap: 0.5rem;
  `,
  lg: css`
    padding: 0.875rem 1.75rem;
    font-size: 1.0625rem;
    border-radius: 10px;
    gap: 0.625rem;
  `,
};

// ─── Variant Styles ───────────────────────────────────────────────────────────

const variantMap: Record<ButtonVariant, ReturnType<typeof css>> = {
  solid: css`
    background: linear-gradient(135deg, #6366f1 0%, #4f46e5 100%);
    color: #ffffff;
    border: 2px solid transparent;

    &:hover:not(:disabled) {
      background: linear-gradient(135deg, #818cf8 0%, #6366f1 100%);
      box-shadow:
        0 4px 15px rgba(99, 102, 241, 0.45),
        0 1px 3px rgba(0, 0, 0, 0.12);
      transform: translateY(-1px);
    }

    &:active:not(:disabled) {
      background: linear-gradient(135deg, #4f46e5 0%, #4338ca 100%);
      transform: translateY(0px);
      box-shadow: 0 1px 4px rgba(99, 102, 241, 0.3);
    }
  `,
  outline: css`
    background: transparent;
    color: #6366f1;
    border: 2px solid #6366f1;

    &:hover:not(:disabled) {
      background: rgba(99, 102, 241, 0.08);
      border-color: #818cf8;
      color: #818cf8;
      box-shadow: 0 4px 12px rgba(99, 102, 241, 0.2);
      transform: translateY(-1px);
    }

    &:active:not(:disabled) {
      background: rgba(99, 102, 241, 0.15);
      transform: translateY(0px);
    }
  `,
  ghost: css`
    background: transparent;
    color: #6366f1;
    border: 2px solid transparent;

    &:hover:not(:disabled) {
      background: rgba(99, 102, 241, 0.1);
      color: #4f46e5;
      transform: translateY(-1px);
    }

    &:active:not(:disabled) {
      background: rgba(99, 102, 241, 0.18);
      transform: translateY(0px);
    }
  `,
};

// ─── Styled Components ────────────────────────────────────────────────────────

const StyledButton = styled.button<{
  $size: ButtonSize;
  $variant: ButtonVariant;
  $fullWidth: boolean;
  $isLoading: boolean;
}>`
  /* Base */
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  cursor: pointer;
  font-family: inherit;
  font-weight: 600;
  letter-spacing: 0.01em;
  line-height: 1;
  white-space: nowrap;
  user-select: none;
  outline: none;
  text-decoration: none;
  transition:
    background 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.15s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    opacity 0.2s ease;

  /* Size */
  ${({ $size }) => sizeMap[$size]}

  /* Variant */
  ${({ $variant }) => variantMap[$variant]}

  /* Full width */
  ${({ $fullWidth }) => $fullWidth && "width: 100%;"}

  /* Focus ring */
  &:focus-visible {
    outline: 3px solid rgba(99, 102, 241, 0.5);
    outline-offset: 3px;
  }

  /* Disabled */
  &:disabled {
    opacity: 0.48;
    cursor: not-allowed;
    transform: none;
    box-shadow: none;
    filter: grayscale(20%);
  }

  /* Loading — prevent pointer events but keep layout */
  ${({ $isLoading }) =>
    $isLoading &&
    css`
      cursor: wait;
      pointer-events: none;
    `}

  /* Ripple child */
  .ripple-effect {
    position: absolute;
    border-radius: 50%;
    width: 60px;
    height: 60px;
    background: rgba(255, 255, 255, 0.35);
    transform: scale(0);
    animation: ${ripple} 0.6s linear;
    pointer-events: none;
  }
`;

const ButtonContent = styled.span<{ $isLoading: boolean }>`
  display: inline-flex;
  align-items: center;
  gap: inherit;
  transition: opacity 0.2s ease;
  opacity: ${({ $isLoading }) => ($isLoading ? 0 : 1)};
`;

const LoadingSpinner = styled.span`
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;

  svg {
    animation: ${spin} 0.75s linear infinite;
  }
`;

const IconWrapper = styled.span`
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
`;

// ─── Spinner SVG ──────────────────────────────────────────────────────────────

const SpinnerIcon = () => (
  <svg
    width="1em"
    height="1em"
    viewBox="0 0 24 24"
    fill="none"
    aria-hidden="true"
  >
    <circle
      cx="12"
      cy="12"
      r="10"
      stroke="currentColor"
      strokeWidth="3"
      strokeLinecap="round"
      strokeDasharray="31.416"
      strokeDashoffset="10"
      opacity="0.3"
    />
    <path
      d="M12 2a10 10 0 0 1 10 10"
      stroke="currentColor"
      strokeWidth="3"
      strokeLinecap="round"
    />
  </svg>
);

// ─── Ripple Hook ──────────────────────────────────────────────────────────────

function useRipple() {
  const [ripples, setRipples] = React.useState<
    { id: number; x: number; y: number }[]
  >([]);

  const createRipple = (e: React.MouseEvent<HTMLButtonElement>) => {
    const btn = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - btn.left - 30;
    const y = e.clientY - btn.top - 30;
    const id = Date.now();
    setRipples((prev) => [...prev, { id, x, y }]);
    setTimeout(() => setRipples((prev) => prev.filter((r) => r.id !== id)), 620);
  };

  return { ripples, createRipple };
}

// ─── Component ────────────────────────────────────────────────────────────────

export const PrimaryButton: React.FC<PrimaryButtonProps> = ({
  label,
  size = "md",
  variant = "solid",
  isLoading = false,
  leftIcon,
  rightIcon,
  fullWidth = false,
  disabled,
  onClick,
  ...rest
}) => {
  const { ripples, createRipple } = useRipple();

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (!isLoading && !disabled) {
      createRipple(e);
      onClick?.(e);
    }
  };

  return (
    <StyledButton
      $size={size}
      $variant={variant}
      $fullWidth={fullWidth}
      $isLoading={isLoading}
      disabled={disabled || isLoading}
      onClick={handleClick}
      aria-busy={isLoading}
      aria-label={isLoading ? `${label} — loading` : label}
      {...rest}
    >
      {/* Ripple effects */}
      {ripples.map(({ id, x, y }) => (
        <span
          key={id}
          className="ripple-effect"
          style={{ left: x, top: y }}
        />
      ))}

      {/* Visible content */}
      <ButtonContent $isLoading={isLoading}>
        {leftIcon && <IconWrapper aria-hidden>{leftIcon}</IconWrapper>}
        {label}
        {rightIcon && <IconWrapper aria-hidden>{rightIcon}</IconWrapper>}
      </ButtonContent>

      {/* Loading overlay */}
      {isLoading && (
        <LoadingSpinner aria-hidden>
          <SpinnerIcon />
        </LoadingSpinner>
      )}
    </StyledButton>
  );
};

export default PrimaryButton;
```

