// PrimaryButton.tsx
import React from "react";
import styled, { css, keyframes } from "styled-components";

// ─── Types ───────────────────────────────────────────────────────────────────

interface PrimaryButtonProps {
  label: string;
  onClick?: () => void;
  disabled?: boolean;
  loading?: boolean;
  size?: "sm" | "md" | "lg";
  fullWidth?: boolean;
  icon?: React.ReactNode;
  type?: "button" | "submit" | "reset";
  ariaLabel?: string;
}

// ─── Animations ──────────────────────────────────────────────────────────────

const spin = keyframes`
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
`;

const ripple = keyframes`
  0%   { transform: scale(0); opacity: 0.6; }
  100% { transform: scale(4); opacity: 0; }
`;

// ─── Size Variants ────────────────────────────────────────────────────────────

const sizeStyles = {
  sm: css`
    padding: 0.4rem 0.875rem;
    font-size: 0.8125rem;
    border-radius: 6px;
    gap: 0.375rem;
  `,
  md: css`
    padding: 0.625rem 1.25rem;
    font-size: 0.9375rem;
    border-radius: 8px;
    gap: 0.5rem;
  `,
  lg: css`
    padding: 0.8rem 1.6rem;
    font-size: 1.0625rem;
    border-radius: 10px;
    gap: 0.625rem;
  `,
};

// ─── Styled Components ────────────────────────────────────────────────────────

const StyledButton = styled.button<{
  $size: "sm" | "md" | "lg";
  $fullWidth: boolean;
  $loading: boolean;
}>`
  /* Layout */
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  width: ${({ $fullWidth }) => ($fullWidth ? "100%" : "auto")};

  /* Size */
  ${({ $size }) => sizeStyles[$size]}

  /* Typography */
  font-family: inherit;
  font-weight: 600;
  letter-spacing: 0.01em;
  line-height: 1.25;
  white-space: nowrap;

  /* Appearance */
  color: #ffffff;
  background: linear-gradient(135deg, #6366f1 0%, #4f46e5 100%);
  border: none;
  outline: none;
  cursor: pointer;

  /* Shadow */
  box-shadow:
    0 1px 3px rgba(79, 70, 229, 0.3),
    0 4px 12px rgba(79, 70, 229, 0.2);

  /* Transition */
  transition:
    background 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.15s ease,
    opacity 0.2s ease;

  /* Loading cursor */
  cursor: ${({ $loading }) => ($loading ? "wait" : "pointer")};

  /* ── Hover ── */
  &:hover:not(:disabled) {
    background: linear-gradient(135deg, #818cf8 0%, #6366f1 100%);
    box-shadow:
      0 2px 6px rgba(79, 70, 229, 0.4),
      0 8px 20px rgba(79, 70, 229, 0.3);
    transform: translateY(-1px);
  }

  /* ── Active / Pressed ── */
  &:active:not(:disabled) {
    background: linear-gradient(135deg, #4f46e5 0%, #4338ca 100%);
    box-shadow:
      0 1px 2px rgba(79, 70, 229, 0.3),
      0 2px 6px rgba(79, 70, 229, 0.2);
    transform: translateY(0px);
  }

  /* ── Focus Visible ── */
  &:focus-visible {
    outline: 3px solid rgba(99, 102, 241, 0.5);
    outline-offset: 3px;
  }

  /* ── Disabled ── */
  &:disabled {
    background: linear-gradient(135deg, #a5b4fc 0%, #818cf8 100%);
    box-shadow: none;
    opacity: 0.55;
    cursor: not-allowed;
    transform: none;
  }

  /* ── Ripple child ── */
  .ripple {
    position: absolute;
    border-radius: 50%;
    width: 60px;
    height: 60px;
    background: rgba(255, 255, 255, 0.4);
    pointer-events: none;
    animation: ${ripple} 0.6s linear;
  }
`;

const Spinner = styled.span`
  display: inline-block;
  width: 1em;
  height: 1em;
  border: 2px solid rgba(255, 255, 255, 0.35);
  border-top-color: #ffffff;
  border-radius: 50%;
  animation: ${spin} 0.7s linear infinite;
  flex-shrink: 0;
`;

const IconWrapper = styled.span`
  display: inline-flex;
  align-items: center;
  font-size: 1.1em;
  flex-shrink: 0;
`;

const Label = styled.span`
  display: inline-block;
`;

// ─── Component ────────────────────────────────────────────────────────────────

const PrimaryButton: React.FC<PrimaryButtonProps> = ({
  label,
  onClick,
  disabled = false,
  loading = false,
  size = "md",
  fullWidth = false,
  icon,
  type = "button",
  ariaLabel,
}) => {
  // ── Ripple Effect ──
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (disabled || loading) return;

    const button = e.currentTarget;
    const circle = document.createElement("span");
    const rect = button.getBoundingClientRect();

    circle.className = "ripple";
    circle.style.left = `${e.clientX - rect.left - 30}px`;
    circle.style.top = `${e.clientY - rect.top - 30}px`;

    button.appendChild(circle);
    setTimeout(() => circle.remove(), 620);

    onClick?.();
  };

  const isDisabled = disabled || loading;

  return (
    <StyledButton
      type={type}
      disabled={isDisabled}
      onClick={handleClick}
      $size={size}
      $fullWidth={fullWidth}
      $loading={loading}
      aria-label={ariaLabel ?? label}
      aria-busy={loading}
      aria-disabled={isDisabled}
    >
      {loading ? (
        <Spinner aria-hidden="true" />
      ) : (
        icon && <IconWrapper aria-hidden="true">{icon}</IconWrapper>
      )}
      <Label>{loading ? "Loading…" : label}</Label>
    </StyledButton>
  );
};

export default PrimaryButton;
