  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  cursor: pointer;
  font-family: inherit;
  font-weight: 600;
  letter-spacing: 0.01em;
  line-height: 1;
  white-space: nowrap;
  user-select: none;
  outline: none;

  /* Transitions */
  transition:
    background 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.15s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    opacity 0.2s ease;

  /* Width */
  width: ${({ $fullWidth }) => ($fullWidth ? "100%" : "auto")};

  /* Size */
  ${({ $size }) => sizeStyles[$size]}

  /* Variant */
  ${({ $variant }) => variantStyles[$variant]}

  /* Focus-visible ring */
  &:focus-visible {
    outline: 3px solid rgba(99, 102, 241, 0.55);
    outline-offset: 3px;
  }

  /* Disabled */
  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    transform: none !important;
    box-shadow: none !important;
  }

  /* Loading — hide content shift */
  ${({ $isLoading }) =>
    $isLoading &&
    css`
      cursor: wait;
      pointer-events: none;
    `}

  /* Ripple child */
  .ripple-effect {
    position: absolute;
    border-radius: 50%;
    width: 40px;
    height: 40px;
    background: rgba(255, 255, 255, 0.35);
    animation: ${ripple} 0.55s linear forwards;
    pointer-events: none;
    transform-origin: center;
  }
`;

const ContentWrapper = styled.span<{ $isLoading: boolean }>`
  display: inline-flex;
  align-items: center;
  gap: inherit;
  opacity: ${({ $isLoading }) => ($isLoading ? 0 : 1)};
  transition: opacity 0.15s ease;
`;

const LoadingOverlay = styled.span`
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
`;

const Spinner = styled.span`
  width: 1em;
  height: 1em;
  border: 2px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: ${spin} 0.7s linear infinite;
  flex-shrink: 0;
`;

// ─── Component ────────────────────────────────────────────────────────────────

const PrimaryButton: React.FC<PrimaryButtonProps> = ({
  label,
  size = "md",
  variant = "solid",
  isLoading = false,
  leftIcon,
  rightIcon,
  fullWidth = false,
  disabled,
  onClick,
  ...rest
}) => {
  // ── Ripple handler ──────────────────────────────────────────────────────────
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (isLoading || disabled) return;

    const button = e.currentTarget;
    const rect = button.getBoundingClientRect();
    const rippleEl = document.createElement("span");

    rippleEl.className = "ripple-effect";
    rippleEl.style.left = `${e.clientX - rect.left - 20}px`;
    rippleEl.style.top = `${e.clientY - rect.top - 20}px`;

    button.appendChild(rippleEl);
    rippleEl.addEventListener("animationend", () => rippleEl.remove());

    onClick?.(e);
  };

  return (
    <StyledButton
      $size={size}
      $variant={variant}
      $fullWidth={fullWidth}
      $isLoading={isLoading}
      disabled={disabled || isLoading}
      onClick={handleClick}
      aria-busy={isLoading}
      aria-disabled={disabled || isLoading}
      {...rest}
    >
      {/* Visible label + icons */}
      <ContentWrapper $isLoading={isLoading}>
        {leftIcon && <span aria-hidden="true">{leftIcon}</span>}
        {label}
        {rightIcon && <span aria-hidden="true">{rightIcon}</span>}
      </ContentWrapper>

      {/* Loading overlay */}
      {isLoading && (
        <LoadingOverlay aria-hidden="true">
          <Spinner />
          <span style={{ fontSize: "0.85em" }}>Loading…</span>
        </LoadingOverlay>
      )}
    </StyledButton>
  );
};

export default PrimaryButton;
