      0 1px 2px rgba(79, 70, 229, 0.3),
      0 2px 6px rgba(79, 70, 229, 0.2);
    transform: translateY(0px);
  }

  /* ── Focus Visible (keyboard nav) ── */
  &:focus-visible {
    outline: 3px solid #a5b4fc;
    outline-offset: 3px;
  }

  /* ── Disabled ── */
  &:disabled {
    background: linear-gradient(135deg, #c7d2fe 0%, #a5b4fc 100%);
    box-shadow: none;
    color: #e0e7ff;
    cursor: not-allowed;
    transform: none;
    opacity: 0.65;
  }

  /* ── Ripple child ── */
  .ripple {
    position: absolute;
    border-radius: 50%;
    width: 8px;
    height: 8px;
    background: rgba(255, 255, 255, 0.5);
    animation: ${ripple} 0.55s linear;
    pointer-events: none;
  }
`;

const Spinner = styled.span`
  display: inline-block;
  width: 1em;
  height: 1em;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-top-color: #ffffff;
  border-radius: 50%;
  animation: ${spin} 0.7s linear infinite;
  flex-shrink: 0;
`;

const LabelWrapper = styled.span<{ $hidden: boolean }>`
  opacity: ${({ $hidden }) => ($hidden ? 0 : 1)};
  display: inline-flex;
  align-items: center;
  gap: inherit;
`;

// ─── Component ───────────────────────────────────────────────────────────────

const PrimaryButton: React.FC<PrimaryButtonProps> = ({
  label,
  onClick,
  disabled = false,
  loading = false,
  fullWidth = false,
  size = "md",
  leftIcon,
  rightIcon,
  type = "button",
  ariaLabel,
}) => {
  // ── Ripple effect ──────────────────────────────────────────────────────────
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (disabled || loading) return;

    const button = e.currentTarget;
    const rippleEl = document.createElement("span");
    const rect = button.getBoundingClientRect();

    rippleEl.className = "ripple";
    rippleEl.style.left = `${e.clientX - rect.left - 4}px`;
    rippleEl.style.top = `${e.clientY - rect.top - 4}px`;

    button.appendChild(rippleEl);
    rippleEl.addEventListener("animationend", () => rippleEl.remove());

    onClick?.();
  };

  const isDisabled = disabled || loading;

  return (
    <StyledButton
      type={type}
      disabled={isDisabled}
      onClick={handleClick}
      $fullWidth={fullWidth}
      $size={size}
      $loading={loading}
      aria-label={ariaLabel ?? label}
      aria-disabled={isDisabled}
      aria-busy={loading}
    >
      {loading && <Spinner aria-hidden="true" />}

      <LabelWrapper $hidden={false}>
        {leftIcon && !loading && <span aria-hidden="true">{leftIcon}</span>}
        {label}
        {rightIcon && !loading && <span aria-hidden="true">{rightIcon}</span>}
      </LabelWrapper>
    </StyledButton>
  );
};

export default PrimaryButton;
