// PrimaryButton.tsx
import React from "react";
import styled, { css, keyframes } from "styled-components";

// ─── Types ───────────────────────────────────────────────────────────────────

type ButtonSize = "sm" | "md" | "lg";
type ButtonVariant = "solid" | "outline" | "ghost";

interface PrimaryButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  label: string;
  size?: ButtonSize;
  variant?: ButtonVariant;
  isLoading?: boolean;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  fullWidth?: boolean;
}

// ─── Animations ──────────────────────────────────────────────────────────────

const spin = keyframes`
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
`;

const ripple = keyframes`
  0%   { transform: scale(0); opacity: 0.6; }
  100% { transform: scale(4); opacity: 0; }
`;

// ─── Size Map ─────────────────────────────────────────────────────────────────

const sizeStyles: Record<ButtonSize, ReturnType<typeof css>> = {
  sm: css`
    padding: 0.375rem 0.875rem;
    font-size: 0.8125rem;
    border-radius: 6px;
    gap: 0.375rem;
  `,
  md: css`
    padding: 0.625rem 1.25rem;
    font-size: 0.9375rem;
    border-radius: 8px;
    gap: 0.5rem;
  `,
  lg: css`
    padding: 0.875rem 1.75rem;
    font-size: 1.0625rem;
    border-radius: 10px;
    gap: 0.625rem;
  `,
};

// ─── Variant Map ──────────────────────────────────────────────────────────────

const variantStyles: Record<ButtonVariant, ReturnType<typeof css>> = {
  solid: css`
    background: linear-gradient(135deg, #6366f1 0%, #4f46e5 100%);
    color: #ffffff;
    border: 2px solid transparent;

    &:hover:not(:disabled) {
      background: linear-gradient(135deg, #818cf8 0%, #6366f1 100%);
      box-shadow:
        0 4px 15px rgba(99, 102, 241, 0.45),
        0 1px 3px rgba(0, 0, 0, 0.12);
      transform: translateY(-1px);
    }

    &:active:not(:disabled) {
      background: linear-gradient(135deg, #4f46e5 0%, #4338ca 100%);
      box-shadow: 0 1px 4px rgba(99, 102, 241, 0.3);
      transform: translateY(0);
    }
  `,
  outline: css`
    background: transparent;
    color: #6366f1;
    border: 2px solid #6366f1;

    &:hover:not(:disabled) {
      background: rgba(99, 102, 241, 0.08);
      box-shadow: 0 4px 12px rgba(99, 102, 241, 0.2);
      transform: translateY(-1px);
    }

    &:active:not(:disabled) {
      background: rgba(99, 102, 241, 0.15);
      transform: translateY(0);
    }
  `,
  ghost: css`
    background: transparent;
    color: #6366f1;
    border: 2px solid transparent;

    &:hover:not(:disabled) {
      background: rgba(99, 102, 241, 0.1);
      transform: translateY(-1px);
    }

    &:active:not(:disabled) {
      background: rgba(99, 102, 241, 0.18);
      transform: translateY(0);
    }
  `,
};

// ─── Styled Components ────────────────────────────────────────────────────────

const StyledButton = styled.button<{
  $size: ButtonSize;
  $variant: ButtonVariant;
  $fullWidth: boolean;
  $isLoading: boolean;
}>`
  /* Layout */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  width: ${({ $fullWidth }) => ($fullWidth ? "100%" : "auto")};

  /* Typography */
  font-family: inherit;
  font-weight: 600;
  letter-spacing: 0.01em;
  line-height: 1;
  white-space: nowrap;

  /* Interaction */
  cursor: ${({ $isLoading }) => ($isLoading ? "wait" : "pointer")};
  user-select: none;
  outline: none;
  transition:
    background 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.15s ease,
    opacity 0.2s ease,
    border-color 0.2s ease;

  /* Focus ring */
  &:focus-visible {
    outline: 3px solid rgba(99, 102, 241, 0.6);
    outline-offset: 3px;
  }

  /* Disabled state */
  &:disabled {
    opacity: 0.48;
    cursor: not-allowed;
    transform: none !important;
    box-shadow: none !important;
  }

  /* Ripple child */
  .ripple {
    position: absolute;
    border-radius: 50%;
    width: 60px;
    height: 60px;
    background: rgba(255, 255, 255, 0.35);
    animation: ${ripple} 0.55s linear;
    pointer-events: none;
    transform-origin: center;
  }

  /* Size + Variant */
  ${({ $size }) => sizeStyles[$size]}
  ${({ $variant }) => variantStyles[$variant]}
`;

const Spinner = styled.span`
  display: inline-block;
  width: 1em;
  height: 1em;
  border: 2px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: ${spin} 0.7s linear infinite;
  flex-shrink: 0;
`;

const IconWrapper = styled.span`
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  font-size: 1.1em;
`;

const LabelWrapper = styled.span<{ $hidden: boolean }>`
  transition: opacity 0.2s;
  opacity: ${({ $hidden }) => ($hidden ? 0 : 1)};
`;

// ─── Component ────────────────────────────────────────────────────────────────

const PrimaryButton: React.FC<PrimaryButtonProps> = ({
  label,
  size = "md",
  variant = "solid",
  isLoading = false,
  leftIcon,
  rightIcon,
  fullWidth = false,
  disabled,
  onClick,
  ...rest
}) => {
  // ── Ripple effect ──────────────────────────────────────────────────────────
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (isLoading || disabled) return;

    const btn = e.currentTarget;
    const rect = btn.getBoundingClientRect();
    const rippleEl = document.createElement("span");
    rippleEl.className = "ripple";
    rippleEl.style.left = `${e.clientX - rect.left - 30}px`;
    rippleEl.style.top = `${e.clientY - rect.top - 30}px`;
    btn.appendChild(rippleEl);
    rippleEl.addEventListener("animationend", () => rippleEl.remove());

    onClick?.(e);
  };

  return (
    <StyledButton
      $size={size}
      $variant={variant}
      $fullWidth={fullWidth}
      $isLoading={isLoading}
      disabled={disabled || isLoading}
      onClick={handleClick}
      aria-busy={isLoading}
      aria-label={isLoading ? `${label} – loading` : label}
      {...rest}
    >
      {/* Left icon / spinner */}
      {isLoading ? (
        <Spinner aria-hidden="true" />
      ) : leftIcon ? (
        <IconWrapper aria-hidden="true">{leftIcon}</IconWrapper>
      ) : null}

      {/* Label */}
      <LabelWrapper $hidden={false}>{label}</LabelWrapper>

      {/* Right icon */}
      {!isLoading && rightIcon && (
        <IconWrapper aria-hidden="true">{rightIcon}</IconWrapper>
      )}
    </StyledButton>
  );
};

export default PrimaryButton;
