        </div>
      </section>

      {/* Full Width */}
      <section>
        <h3>Full Width</h3>
        <PrimaryButton label="Submit Form" fullWidth rightIcon={<ArrowIcon />} />
      </section>

    </div>
  );
}
```

## State Reference

| State | Behaviour |
|---|---|
| **Default** | Indigo gradient, smooth shadow |
| **Hover** | Lighter gradient, lifted shadow, `translateY(-1px)` |
| **Active / Press** | Darker gradient, pressed down, `translateY(0)` |
| **Focus-visible** | Accessible indigo outline ring (keyboard only) |
| **Disabled** | 48 % opacity, `grayscale`, `cursor: not-allowed`, no interactions |
| **Loading** | Spinner replaces left icon, `cursor: wait`, `aria-busy` set |

## Key Design Decisions

- **`pointer-events: none` on disabled** — prevents hover/active styles leaking through CSS specificity tricks  
- **Ripple effect** — purely CSS-animated `<span>` elements injected on click; cleaned up after 600 ms  
- **`focus-visible` only** — focus ring appears for keyboard navigation but not mouse clicks  
- **`aria-busy` + `aria-label`** — screen readers announce the loading state without extra hidden text  
- **Transient props (`$size`, `$variant`)** — prefixed with `$` so styled-components doesn't forward them to the DOM

# Primary Action Button Component

## Component Implementation

```tsx
// PrimaryButton.tsx
import React, { ButtonHTMLAttributes } from "react";
import styled, { css, keyframes } from "styled-components";

// ─── Types ───────────────────────────────────────────────────────────────────

type ButtonSize = "sm" | "md" | "lg";
type ButtonVariant = "solid" | "outline" | "ghost";

interface PrimaryButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  label: string;
  size?: ButtonSize;
  variant?: ButtonVariant;
  isLoading?: boolean;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  fullWidth?: boolean;
}

// ─── Animations ──────────────────────────────────────────────────────────────

const spin = keyframes`
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
`;

const ripple = keyframes`
  0%   { transform: scale(0); opacity: 0.6; }
  100% { transform: scale(4); opacity: 0; }
`;

// ─── Size Styles ─────────────────────────────────────────────────────────────

const sizeStyles = {
  sm: css`
    padding: 0.375rem 0.875rem;
    font-size: 0.8125rem;
    border-radius: 0.375rem;
    gap: 0.375rem;
  `,
  md: css`
    padding: 0.625rem 1.25rem;
    font-size: 0.9375rem;
    border-radius: 0.5rem;
    gap: 0.5rem;
  `,
  lg: css`
    padding: 0.875rem 1.75rem;
    font-size: 1.0625rem;
    border-radius: 0.625rem;
    gap: 0.625rem;
  `,
};

// ─── Variant Styles ───────────────────────────────────────────────────────────

const variantStyles = {
  solid: css`
    background: linear-gradient(135deg, #6366f1 0%, #4f46e5 100%);
    color: #ffffff;
    border: 2px solid transparent;
    box-shadow: 0 2px 8px rgba(99, 102, 241, 0.35);

    &:hover:not(:disabled) {
      background: linear-gradient(135deg, #818cf8 0%, #6366f1 100%);
      box-shadow: 0 4px 16px rgba(99, 102, 241, 0.5);
      transform: translateY(-1px);
    }

    &:active:not(:disabled) {
      background: linear-gradient(135deg, #4f46e5 0%, #4338ca 100%);
      box-shadow: 0 1px 4px rgba(99, 102, 241, 0.3);
      transform: translateY(0);
    }
  `,
  outline: css`
    background: transparent;
    color: #6366f1;
    border: 2px solid #6366f1;
    box-shadow: none;

    &:hover:not(:disabled) {
      background: rgba(99, 102, 241, 0.08);
      border-color: #4f46e5;
      color: #4f46e5;
      box-shadow: 0 2px 8px rgba(99, 102, 241, 0.2);
      transform: translateY(-1px);
    }

    &:active:not(:disabled) {
      background: rgba(99, 102, 241, 0.15);
      transform: translateY(0);
    }
  `,
  ghost: css`
    background: transparent;
    color: #6366f1;
    border: 2px solid transparent;
    box-shadow: none;

    &:hover:not(:disabled) {
      background: rgba(99, 102, 241, 0.1);
      color: #4f46e5;
      transform: translateY(-1px);
    }

    &:active:not(:disabled) {
      background: rgba(99, 102, 241, 0.18);
      transform: translateY(0);
    }
  `,
};

// ─── Styled Components ────────────────────────────────────────────────────────

const StyledButton = styled.button<{
  $size: ButtonSize;
  $variant: ButtonVariant;
  $fullWidth: boolean;
  $isLoading: boolean;
}>`
  /* Layout */
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  width: ${({ $fullWidth }) => ($fullWidth ? "100%" : "auto")};

  /* Typography */
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  font-weight: 600;
  letter-spacing: 0.01em;
  white-space: nowrap;
  line-height: 1;

  /* Interaction */
  cursor: ${({ $isLoading }) => ($isLoading ? "wait" : "pointer")};
  user-select: none;
  outline: none;
  text-decoration: none;

  /* Transition */
  transition:
    background 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.15s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    opacity 0.2s ease;

  /* Focus ring */
  &:focus-visible {
    outline: 3px solid rgba(99, 102, 241, 0.5);
    outline-offset: 3px;
  }

  /* Disabled state */
  &:disabled {
    opacity: 0.48;
    cursor: not-allowed;
    transform: none !important;
    box-shadow: none !important;
    filter: grayscale(20%);
  }

  /* Ripple effect */
  .ripple {
    position: absolute;
    border-radius: 50%;
    width: 60px;
    height: 60px;
    margin-top: -30px;
    margin-left: -30px;
    background: rgba(255, 255, 255, 0.35);
    animation: ${ripple} 0.55s linear;
    pointer-events: none;
  }

  /* Apply size & variant */
  ${({ $size }) => sizeStyles[$size]}
  ${({ $variant }) => variantStyles[$variant]}
`;

const Spinner = styled.span`
  display: inline-flex;
  width: 1em;
  height: 1em;
  border: 2px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: ${spin} 0.7s linear infinite;
  flex-shrink: 0;
`;

const IconWrapper = styled.span`
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  font-size: 1.1em;
`;

const LabelWrapper = styled.span<{ $hidden: boolean }>`
  transition: opacity 0.2s ease;
  opacity: ${({ $hidden }) => ($hidden ? 0 : 1)};
`;

// ─── Component ────────────────────────────────────────────────────────────────

export const PrimaryButton: React.FC<PrimaryButtonProps> = ({
  label,
  size = "md",
  variant = "solid",
  isLoading = false,
  leftIcon,
  rightIcon,
  fullWidth = false,
  disabled,
  onClick,
  ...rest
}) => {
  // ── Ripple handler ──────────────────────────────────────────────────────────
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (disabled || isLoading) return;

    const button = e.currentTarget;
    const circle = document.createElement("span");
    const rect = button.getBoundingClientRect();

    circle.className = "ripple";
    circle.style.left = `${e.clientX - rect.left}px`;
    circle.style.top = `${e.clientY - rect.top}px`;

    button.appendChild(circle);
    setTimeout(() => circle.remove(), 600);

    onClick?.(e);
  };

  return (
    <StyledButton
      $size={size}
      $variant={variant}
      $fullWidth={fullWidth}
      $isLoading={isLoading}
      disabled={disabled || isLoading}
      onClick={handleClick}
      aria-busy={isLoading}
      aria-label={isLoading ? `${label} – loading` : label}
      {...rest}
    >
      {/* Left icon or spinner */}
      {isLoading ? (
        <Spinner aria-hidden="true" />
      ) : (
        leftIcon && <IconWrapper aria-hidden="true">{leftIcon}</IconWrapper>
      )}

      {/* Label */}
      <LabelWrapper $hidden={false}>{label}</LabelWrapper>

      {/* Right icon (hidden during loading) */}
      {!isLoading && rightIcon && (
        <IconWrapper aria-hidden="true">{rightIcon}</IconWrapper>
      )}
    </StyledButton>
  );
};

export default PrimaryButton;
```

