const ProductCard = ({
  image,
  title,
  price,
  originalPrice,
  badge,
  rating,
  reviewCount,
  onAddToCart,
  onWishlist,
}) => {
  const discount = originalPrice
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : null;

  const renderStars = (rating) => {
    return Array.from({ length: 5 }, (_, i) => (
      <span
        key={i}
        className={`star ${i < Math.floor(rating) ? 'filled' : i < rating ? 'half' : ''}`}
      >
