## Product Card Component

Here's a clean, reusable React product card component with TypeScript support:

### Component File: `ProductCard.tsx`

```tsx
import React from "react";

interface ProductCardProps {
  image: string;
  title: string;
  price: number;
  currency?: string;
  discount?: number;
  rating?: number;
  reviewCount?: number;
  onAddToCart?: () => void;
  onWishlist?: () => void;
}

const ProductCard: React.FC<ProductCardProps> = ({
  image,
  title,
  price,
  currency = "USD",
  discount = 0,
  rating = 0,
  reviewCount = 0,
  onAddToCart,
  onWishlist,
}) => {
  const discountedPrice = discount > 0 ? price - (price * discount) / 100 : price;

  const formatPrice = (amount: number, curr: string) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency: curr }).format(amount);

  const renderStars = (rating: number) => {
    return Array.from({ length: 5 }, (_, i) => {
      const filled = i < Math.floor(rating);
      const partial = !filled && i < rating;
      return (
        <span key={i} className={`star ${filled ? "filled" : partial ? "partial" : "empty"}`}>
          ★
        </span>
      );
    });
  };

  return (
    <div className="product-card">
      {/* Discount Badge */}
      {discount > 0 && <span className="badge">{discount}% OFF</span>}

      {/* Wishlist Button */}
      <button className="wishlist-btn" onClick={onWishlist} aria-label="Add to wishlist">
        ♡
      </button>

      {/* Product Image */}
      <div className="image-container">
        <img src={image} alt={title} className="product-image" loading="lazy" />
      </div>

      {/* Product Info */}
      <div className="product-info">
        <h3 className="product-title">{title}</h3>

        {/* Rating */}
        {rating > 0 && (
          <div className="rating">
            <div className="stars">{renderStars(rating)}</div>
            <span className="review-count">({reviewCount})</span>
          </div>
        )}

        {/* Price */}
        <div className="price-container">
          <span className="current-price">{formatPrice(discountedPrice, currency)}</span>
          {discount > 0 && (
            <span className="original-price">{formatPrice(price, currency)}</span>
          )}
        </div>

        {/* Add to Cart Button */}
        <button className="add-to-cart-btn" onClick={onAddToCart}>
          Add to Cart
        </button>
      </div>
    </div>
  );
};

export default ProductCard;
```

