import React from "react";

interface ProductCardProps {
  image: string;
  title: string;
  price: number;
  currency?: string;
  discount?: number;
  rating?: number;
  reviewCount?: number;
  onAddToCart?: () => void;
  onWishlist?: () => void;
}

const ProductCard: React.FC<ProductCardProps> = ({
  image,
  title,
  price,
  currency = "USD",
  discount = 0,
  rating = 0,
  reviewCount = 0,
  onAddToCart,
  onWishlist,
}) => {
  const discountedPrice = discount > 0 ? price - (price * discount) / 100 : price;

  const formatPrice = (amount: number, currencyCode: string): string => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: currencyCode,
    }).format(amount);
  };

  const renderStars = (rating: number) => {
    return Array.from({ length: 5 }, (_, index) => {
      const filled = index < Math.floor(rating);
      const partial = !filled && index < rating;
      return (
        <span
          key={index}
          style={{
            color: filled || partial ? "#f59e0b" : "#d1d5db",
            fontSize: "1rem",
          }}
        >
          {partial ? "½" : "★"}
        </span>
      );
    });
  };

  return (
    <div style={styles.card}>
      {/* Wishlist Button */}
      <button
        style={styles.wishlistButton}
        onClick={onWishlist}
        aria-label="Add to wishlist"
      >
        ♡
      </button>

      {/* Discount Badge */}
      {discount > 0 && (
        <div style={styles.discountBadge}>-{discount}%</div>
      )}

      {/* Product Image */}
      <div style={styles.imageContainer}>
        <img
          src={image}
          alt={title}
          style={styles.image}
          onError={(e) => {
            (e.target as HTMLImageElement).src =
              "https://via.placeholder.com/300x200?text=No+Image";
          }}
        />
      </div>

      {/* Product Info */}
      <div style={styles.content}>
        <h3 style={styles.title}>{title}</h3>

        {/* Rating */}
        {rating > 0 && (
          <div style={styles.ratingContainer}>
            <div style={styles.stars}>{renderStars(rating)}</div>
            <span style={styles.reviewCount}>({reviewCount})</span>
          </div>
        )}

        {/* Price */}
        <div style={styles.priceContainer}>
          <span style={styles.currentPrice}>
            {formatPrice(discountedPrice, currency)}
          </span>
          {discount > 0 && (
            <span style={styles.originalPrice}>
              {formatPrice(price, currency)}
            </span>
          )}
        </div>

        {/* Add to Cart Button */}
        <button
          style={styles.cartButton}
          onClick={onAddToCart}
          aria-label={`Add ${title} to cart`}
        >
          🛒 Add to Cart
        </button>
      </div>
    </div>
  );
};

