### `Modal.css`

```css
/* ── Backdrop ─────────────────────────────────────────────────────────────── */
.modal-backdrop {
  position: fixed;
  inset: 0;                          /* top/right/bottom/left: 0 */
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;

  background-color: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(3px);

  /* Fade-in animation */
  animation: backdropFadeIn 200ms ease forwards;
}

@keyframes backdropFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* ── Panel ────────────────────────────────────────────────────────────────── */
.modal-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-height: calc(100vh - 2rem);

  background: #ffffff;
  border-radius: 12px;
  box-shadow:
    0 20px 60px rgba(0, 0, 0, 0.3),
    0 4px 16px rgba(0, 0, 0, 0.15);

  overflow: hidden;
  outline: none;                     /* focus ring handled by :focus-visible */

  /* Slide-up + fade-in animation */
  animation: panelSlideIn 250ms cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

@keyframes panelSlideIn {
  from {
    opacity: 0;
    transform: translateY(24px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* ── Size variants ────────────────────────────────────────────────────────── */
.modal-panel--sm { max-width: 380px;  }
.modal-panel--md { max-width: 560px;  }
.modal-panel--lg { max-width: 760px;  }
.modal-panel--xl { max-width: 1024px; }

/* ── Header ───────────────────────────────────────────────────────────────── */
.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid #e5e7eb;
  flex-shrink: 0;
}

.modal-title {
  margin: 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: #111827;
  line-height: 1.4;
}

/* ── Close button ─────────────────────────────────────────────────────────── */
.modal-close-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 2rem;
  height: 2rem;
  padding: 0;
  margin-left: auto;

  background: transparent;
  border: none;
  border-radius: 6px;
  color: #6b7280;
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease;
}

.modal-close-btn:hover {
  background-color: #f3f4f6;
  color: #111827;
}

.modal-close-btn:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 2px;
}

/* ── Body ─────────────────────────────────────────────────────────────────── */
.modal-body {
  padding: 1.5rem;
  overflow-y: auto;
  flex: 1;
  color: #374151;
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ── Footer ───────────────────────────────────────────────────────────────── */
.modal-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.75rem;
  padding: 1rem 1.5rem;
  border-top: 1px solid #e5e7eb;
  flex-shrink: 0;
  background: #f9fafb;
}

/* ── Responsive ───────────────────────────────────────────────────────────── */
@media (max-width: 480px) {
  .modal-backdrop {
    align-items: flex-end;
    padding: 0;
  }

  .modal-panel {
    border-radius: 16px 16px 0 0;
    max-height: 90vh;
    animation: panelSlideUp 300ms cubic-bezier(0.34, 1.2, 0.64, 1) forwards;
  }

  @keyframes panelSlideUp {
    from { transform: translateY(100%); }
    to   { transform: translateY(0);    }
  }
}
