import React, { useState } from "react";
import Modal from "./Modal";

const App: React.FC = () => {
  const [open, setOpen] = useState(false);

  return (
    <div style={{ padding: "2rem", fontFamily: "sans-serif" }}>
      <button
        onClick={() => setOpen(true)}
        style={{
          padding: "0.6rem 1.4rem",
          fontSize: "1rem",
          borderRadius: "8px",
          border: "none",
          background: "#6366f1",
          color: "#fff",
          cursor: "pointer",
        }}
      >
        Open Modal
      </button>

      <Modal
        isOpen={open}
        onClose={() => setOpen(false)}
        title="Confirm Action"
        size="md"
        footer={
          <>
            <button
              onClick={() => setOpen(false)}
              style={{
                padding: "0.5rem 1.2rem",
                borderRadius: "6px",
                border: "1px solid #d1d5db",
                background: "#fff",
                cursor: "pointer",
              }}
            >
              Cancel
            </button>
            <button
              onClick={() => {
                alert("Confirmed!");
                setOpen(false);
              }}
              style={{
                padding: "0.5rem 1.2rem",
                borderRadius: "6px",
                border: "none",
                background: "#6366f1",
                color: "#fff",
                cursor: "pointer",
              }}
            >
              Confirm
            </button>
          </>
        }
      >
        <p>
          Are you sure you want to proceed? This action cannot be undone.
        </p>
      </Modal>
    </div>
  );
};

export default App;
