## Feature Summary

| Feature | Details |
|---|---|
| **Portal rendering** | Mounts into `document.body` via `createPortal` |
| **Backdrop** | Fixed, full-screen, semi-transparent + blur |
| **Animations** | Backdrop fade-in; panel slide-up + scale with spring easing |
| **Focus trap** | Tab / Shift+Tab cycles within the modal |
| **Focus restore** | Returns focus to the trigger element on close |
| **Keyboard** | `Escape` closes the modal |
| **Scroll lock** | `overflow: hidden` on `<body>` while open |
| **Size variants** | `sm` / `md` / `lg` / `xl` max-width presets |
| **Mobile** | Bottom-sheet style on small screens |
| **Accessibility** | `role="dialog"`, `aria-modal`, `aria-labelledby` |

```jsx
import React from "react";

export default function PrimaryButton({
  children,
  disabled = false,
  onClick,
  type = "button",
}) {
  const baseStyles = {
    padding: "10px 16px",
    border: "none",
    borderRadius: "8px",
    fontSize: "16px",
    fontWeight: 600,
    color: "#ffffff",
    backgroundColor: disabled ? "#9ca3af" : "#2563eb",
    cursor: disabled ? "not-allowed" : "pointer",
    transition: "background-color 0.2s ease, transform 0.1s ease",
    opacity: disabled ? 0.7 : 1,
  };

  const hoverStyles = !disabled
    ? {
        backgroundColor: "#1d4ed8",
      }
    : {};

  const [isHovered, setIsHovered] = React.useState(false);

  return (
    <button
      type={type}
      disabled={disabled}
      onClick={onClick}
      style={{
        ...baseStyles,
        ...(isHovered ? hoverStyles : {}),
      }}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {children}
    </button>
  );
}
