```jsx
import React from "react";

export default function PrimaryButton({
  children = "Click me",
  disabled = false,
  onClick,
  type = "button",
}) {
  const styles = {
    button: {
      backgroundColor: disabled ? "#9CA3AF" : "#2563EB",
      color: "#FFFFFF",
      border: "none",
      borderRadius: "8px",
      padding: "12px 18px",
      fontSize: "16px",
      fontWeight: 600,
      cursor: disabled ? "not-allowed" : "pointer",
      transition: "background-color 0.2s ease, transform 0.1s ease",
      outline: "none",
      opacity: disabled ? 0.7 : 1,
    },
  };

  const handleMouseEnter = (e) => {
    if (!disabled) e.currentTarget.style.backgroundColor = "#1D4ED8";
  };

  const handleMouseLeave = (e) => {
    if (!disabled) e.currentTarget.style.backgroundColor = "#2563EB";
  };

  const handleMouseDown = (e) => {
    if (!disabled) e.currentTarget.style.transform = "translateY(1px)";
  };

  const handleMouseUp = (e) => {
    if (!disabled) e.currentTarget.style.transform = "translateY(0)";
  };

  return (
    <button
      type={type}
      disabled={disabled}
      onClick={onClick}
      style={styles.button}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
    >
      {children}
    </button>
  );
}
```

