// src/components/PrimaryButton/PrimaryButton.js

import React from 'react';
import PropTypes from 'prop-types';
import styles from './PrimaryButton.module.css'; // Import the CSS module

/**
 * A primary action button for key user interactions.
 * It includes distinct styles for hover and disabled states.
 */
const PrimaryButton = ({
  children,
  onClick,
  disabled = false,
  type = 'button',
  ...rest // Pass any other props like aria-label, etc.
}) => {
  return (
    <button
      type={type}
      className={styles.button}
      onClick={onClick}
      disabled={disabled}
      {...rest}
    >
      {children}
    </button>
  );
};

// PropTypes help with component documentation and error checking
PrimaryButton.propTypes = {
  /**
   * The content to display inside the button (e.g., text or an icon).
   */
  children: PropTypes.node.isRequired,
  /**
   * The function to call when the button is clicked.
   */
  onClick: PropTypes.func,
  /**
   * If true, the button will be in a disabled state and cannot be clicked.
   */
  disabled: PropTypes.bool,
  /**
   * The native HTML button type attribute.
   */
  type: PropTypes.oneOf(['button', 'submit', 'reset']),
};

export default PrimaryButton;
```

#### Key Features of the Component:

*   **Props Destructuring:** We pull out the props we need (`children`, `onClick`, `disabled`, `type`) and use default values for `disabled` and `type` to make the component easier to use.
*   **`...rest` Operator:** This is a crucial pattern for reusable components. It allows you to pass any other standard HTML attribute (like `id`, `aria-label`, `data-testid`) directly to the underlying `<button>` element without having to define them as props explicitly.
*   **CSS Modules Integration:** `import styles from './PrimaryButton.module.css'` creates a `styles` object. `className={styles.button}` then applies the unique, scoped class name from our CSS file.
*   **PropTypes:** This is a best practice for documenting your component's API and catching bugs. It tells other developers (and yourself) what props the component expects and what their types should be.

