Create a file at `src/components/ProductCard.js`:
```javascript
import React from 'react';
import PropTypes from 'prop-types';
import './ProductCard.css';

/**
 * A component that displays a product card with an image, title, and price.
 * @param {object} props - The props for the component.
 * @param {string} props.imageUrl - The URL of the product image.
 * @param {string} props.title - The title of the product.
 * @param {number} props.price - The price of the product.
 */
const ProductCard = ({ imageUrl, title, price }) => {
  // Formats the price to two decimal places and adds a currency symbol.
  const formattedPrice = `$${price.toFixed(2)}`;

  return (
    <div className="product-card">
      <img src={imageUrl} alt={title} className="product-image" />
      <div className="product-info">
        <h2 className="product-title">{title}</h2>
        <p className="product-price">{formattedPrice}</p>
      </div>
    </div>
  );
};

// Define PropTypes for type-checking. This is a best practice for reusable components.
ProductCard.propTypes = {
  imageUrl: PropTypes.string.isRequired,
  title: PropTypes.string.isRequired,
  price: PropTypes.number.isRequired,
};

export default ProductCard;
```

