```jsx
// src/components/Modal.js

import React, { useEffect } from 'react';
import ReactDOM from 'react-dom';
import './Modal.css';

const Modal = ({ isOpen, onClose, children }) => {
  // Return null if the modal is not open
  if (!isOpen) {
    return null;
  }

  // Effect to handle the 'Escape' key press for closing the modal
  useEffect(() => {
    const handleEscapeKey = (event) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    // Add event listener when the modal is opened
    document.addEventListener('keydown', handleEscapeKey);

    // Clean up the event listener when the modal is closed or component unmounts
    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, [onClose]); // Dependency array ensures the effect runs only when onClose changes

  // Use ReactDOM.createPortal to render the modal into the 'modal-root' div
  return ReactDOM.createPortal(
    <div className="modal-backdrop" onClick={onClose}>
      {/* 
        The e.stopPropagation() on the content div prevents the modal from closing 
        when you click inside the content area. The click event won't "bubble up"
        to the backdrop.
      */}
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        {children}
      </div>
    </div>,
    document.getElementById('modal-root')
  );
};

export default Modal;
```

