### 1. The Modal Component (`Modal.js`)

This is the core component. It uses `ReactDOM.createPortal` to render the modal outside of the main component hierarchy, which is the best practice for avoiding `z-index` and `overflow` issues.

```jsx
// src/components/Modal.js

import React, { useEffect } from 'react';
import ReactDOM from 'react-dom';
import './Modal.css';

const Modal = ({ isOpen, onClose, children }) => {
  // Effect to handle the 'Escape' key press
  useEffect(() => {
    const handleEscape = (event) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscape);
    }

    // Cleanup function to remove the event listener
    return () => {
      document.removeEventListener('keydown', handleEscape);
    };
  }, [isOpen, onClose]);

  // Don't render anything if the modal is not open
  if (!isOpen) {
    return null;
  }

  // Use a portal to render the modal at the end of the body
  return ReactDOM.createPortal(
    <div className="modal-backdrop" onClick={onClose}>
      <div 
        className="modal-content" 
        onClick={(e) => e.stopPropagation()} // Prevent click from closing modal
      >
        <button className="modal-close-button" onClick={onClose}>
          &times;
        </button>
        {children}
      </div>
    </div>,
    document.getElementById('modal-root') // Target element in index.html
  );
};

export default Modal;
```

