### 1. The Modal Component (`Modal.js`)

This is the core component. It handles the logic for displaying the modal, closing it, and rendering its content.

```jsx
// src/Modal.js

import React, { useEffect } from 'react';
import ReactDOM from 'react-dom';
import './Modal.css';

const Modal = ({ isOpen, onClose, children }) => {
  // Return null if the modal is not open
  if (!isOpen) {
    return null;
  }

  // Effect to handle the 'Escape' key press for closing the modal
  useEffect(() => {
    const handleEscape = (event) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    // Add event listener when the modal is opened
    document.addEventListener('keydown', handleEscape);

    // Clean up the event listener when the modal is closed or component unmounts
    return () => {
      document.removeEventListener('keydown', handleEscape);
    };
  }, [onClose]); // Dependency array ensures this effect runs only when onClose changes

  // Use a portal to render the modal at the root of the document
  // This avoids z-index issues with other components
  return ReactDOM.createPortal(
    <div 
      className="modal-backdrop" 
      onClick={onClose} // Close modal when backdrop is clicked
      role="dialog"
      aria-modal="true"
    >
      <div 
        className="modal-content" 
        onClick={(e) => e.stopPropagation()} // Prevent click from bubbling up to the backdrop
      >
        <button onClick={onClose} className="modal-close-button" aria-label="Close modal">
          &times;
        </button>
        {children}
      </div>
    </div>,
    document.body // The modal will be appended to the <body> tag
  );
};

export default Modal;
```

