### Step 2: Create the Modal Component

This is the main component. It handles the logic for displaying the modal, closing it, and rendering its content via a portal.

Create a file named `Modal.js`.

```jsx
// src/Modal.js

import React, { useEffect } from 'react';
import ReactDOM from 'react-dom';
import './Modal.css';

const Modal = ({ isOpen, onClose, children }) => {
  // Effect to handle body scroll and Escape key press
  useEffect(() => {
    // Prevent background scrolling when the modal is open
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }

    // Function to handle the 'Escape' key press
    const handleKeyDown = (event) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    // Add event listener when the modal is open
    if (isOpen) {
      document.addEventListener('keydown', handleKeyDown);
    }

    // Cleanup function to remove the event listener and restore body scroll
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'unset';
    };
  }, [isOpen, onClose]); // Rerun effect if isOpen or onClose changes

  // If the modal is not open, don't render anything
  if (!isOpen) {
    return null;
  }

  // Use ReactDOM.createPortal to render the modal into the 'modal-root' div
  return ReactDOM.createPortal(
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        {/* The stopPropagation above prevents the modal from closing when clicking inside the content */}
        {children}
      </div>
    </div>,
    document.getElementById('modal-root')
  );
};

export default Modal;
```

