### 1. The `Modal` Component

This is the core, reusable component. It handles the backdrop, the content panel, and the closing logic.

`src/components/Modal.js`
```jsx
import React, { useEffect } from 'react';
import ReactDOM from 'react-dom';
import './Modal.css';

const Modal = ({ isOpen, onClose, children }) => {
  // If the modal is not open, don't render anything
  if (!isOpen) {
    return null;
  }

  // Effect to handle the "Escape" key press
  useEffect(() => {
    const handleEscape = (event) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    // Add event listener when the modal is opened
    document.addEventListener('keydown', handleEscape);

    // Clean up the event listener when the modal is closed
    return () => {
      document.removeEventListener('keydown', handleEscape);
    };
  }, [onClose]); // Dependency array ensures this effect runs only when onClose changes

  // Effect to disable body scroll when the modal is open
  useEffect(() => {
    document.body.style.overflow = 'hidden';

    // Re-enable scroll when the component unmounts
    return () => {
      document.body.style.overflow = 'auto';
    };
  }, []); // Empty dependency array means this runs only on mount and unmount

  // Use a portal to render the modal into a specific DOM node
  // This is crucial for stacking context and accessibility
  return ReactDOM.createPortal(
    <div 
      className="modal-backdrop" 
      onClick={onClose} // Close modal on backdrop click
    >
      <div 
        className="modal-content" 
        onClick={(e) => e.stopPropagation()} // Prevent click from bubbling up to the backdrop
        role="dialog"
        aria-modal="true"
      >
        <button className="modal-close-button" onClick={onClose} aria-label="Close modal">
          &times;
        </button>
        {children}
      </div>
    </div>,
    document.getElementById('modal-root') // The target DOM node
  );
};

export default Modal;
```

