### 1. The Modal Component (`Modal.js`)

This component is the core of our solution. It accepts `isOpen`, `onClose`, and `children` as props, making it highly reusable.

```jsx
// src/components/Modal.js

import React, { useEffect } from 'react';
import './Modal.css';

const Modal = ({ isOpen, onClose, children }) => {
  // Effect to handle the "Escape" key press
  useEffect(() => {
    const handleKeyDown = (event) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    // Add event listener only when the modal is open
    if (isOpen) {
      document.addEventListener('keydown', handleKeyDown);
    }

    // Cleanup function to remove the event listener
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]); // Dependencies ensure the effect runs when isOpen or onClose changes

  // Don't render the modal if it's not open
  if (!isOpen) {
    return null;
  }

  // Function to handle backdrop clicks
  // This prevents the modal from closing when clicking on the content itself
  const handleBackdropClick = (event) => {
    if (event.target === event.currentTarget) {
      onClose();
    }
  };

  return (
    <div className="modal-backdrop" onClick={handleBackdropClick}>
      <div className="modal-content">
        <button className="modal-close-button" onClick={onClose}>
          &times; {/* A simple 'X' for the close button */}
        </button>
        {children}
      </div>
    </div>
  );
};

export default Modal;
```

