<html lang="en">
  <head>
    <!-- ... other head tags -->
    <title>React Modal App</title>
  </head>
  <body>
    <noscript>You need to enable JavaScript to run this app.</noscript>
    <div id="root"></div>
    <!-- 👇 Add this div for the modal portal -->
    <div id="modal-root"></div>
  </body>
</html>
```

