### 1. The Modal Component (`Modal.js`)

This is the core component. It handles the logic for displaying the modal, closing it, and rendering its content.

```jsx
// src/components/Modal.js

import React, { useEffect } from 'react';
import ReactDOM from 'react-dom';
import './Modal.css';

const Modal = ({ isOpen, onClose, children }) => {
  // Return null if the modal is not open
  if (!isOpen) return null;

  // Effect to handle the 'Escape' key press
  useEffect(() => {
    const handleEscapeKey = (e) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };

    // Add event listener when the modal is opened
    document.addEventListener('keydown', handleEscapeKey);

    // Clean up the event listener when the component unmounts or modal closes
    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, [onClose]); // Dependency array ensures effect runs only when onClose changes

  // Use a portal to render the modal at the root of the document
  // This helps to avoid z-index and styling issues.
  return ReactDOM.createPortal(
    <div className="modal-backdrop" onClick={onClose}>
      <div 
        className="modal-content" 
        onClick={(e) => e.stopPropagation()} // Prevents modal from closing when clicking inside the content
      >
        <button className="modal-close-button" onClick={onClose}>
          &times;
        </button>
        {children}
      </div>
    </div>,
    document.body // The modal will be appended to the body element
  );
};

export default Modal;
```

